//! C++ string helpers from `base/str.cpp` that the UI ports need (chat, scoreboard):
//! case-insensitive search and comparison. Strings are byte slices like C strings;
//! offsets are byte offsets, as in C++.

use std::sync::OnceLock;

use crate::protocol::packer::utf8_decode;

/// C++: `UPPER_TO_LOWER_CODEPOINT_MAP` (base/unicode/tolower_data.cpp, generated by
/// scripts/generate_unicode_tolower.py), read from the C++ source itself so the table
/// cannot drift.
fn tolower_map() -> &'static Vec<(i32, i32)> {
    static MAP: OnceLock<Vec<(i32, i32)>> = OnceLock::new();
    MAP.get_or_init(|| {
        let src = include_str!("../../../src/base/unicode/tolower_data.cpp");
        let mut map: Vec<(i32, i32)> = (src.lines())
            .filter_map(|l| {
                let (a, b) = l
                    .trim()
                    .strip_prefix('{')?
                    .strip_suffix("},")?
                    .split_once(',')?;
                Some((a.trim().parse().ok()?, b.trim().parse().ok()?))
            })
            .collect();
        map.sort_unstable();
        map
    })
}

/// C++: `str_utf8_tolower_codepoint` (base/unicode/tolower.cpp).
pub fn tolower_codepoint(code: i32) -> i32 {
    let map = tolower_map();
    map.binary_search_by_key(&code, |&(k, _)| k)
        .map_or(code, |i| map[i].1)
}

/// Byte of a C string held in a slice: past the end reads as the terminator.
pub fn at(s: &[u8], i: usize) -> u8 {
    s.get(i).copied().unwrap_or(0)
}

/// C++: `str_utf8_find_nocase` (str.cpp:1144): the byte offset of the first match of
/// `needle` in `haystack`, comparing lower-cased code points.
pub fn utf8_find_nocase(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    let mut h = 0;
    while at(haystack, h) != 0 {
        let (mut a, mut b) = (h, 0);
        let (mut a_next, mut b_next) = (a, b);
        while at(haystack, a) != 0
            && at(needle, b) != 0
            && tolower_codepoint(utf8_decode(haystack, &mut a_next))
                == tolower_codepoint(utf8_decode(needle, &mut b_next))
        {
            a = a_next;
            b = b_next;
        }
        if at(needle, b) == 0 {
            return Some(h);
        }
        utf8_decode(haystack, &mut h);
    }
    None
}

/// C++: `_stricmp`/`strcasecmp` (`str_comp_nocase`, str.cpp:354): ASCII-only case
/// folding, compared as unsigned bytes up to the terminator.
pub fn comp_nocase(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    comp_nocase_num(a, b, usize::MAX)
}

/// C++: `_strnicmp`/`strncasecmp` (`str_comp_nocase_num`).
pub fn comp_nocase_num(a: &[u8], b: &[u8], num: usize) -> std::cmp::Ordering {
    for i in 0..num {
        let (x, y) = (at(a, i).to_ascii_lowercase(), at(b, i).to_ascii_lowercase());
        if x != y || x == 0 {
            return x.cmp(&y);
        }
    }
    std::cmp::Ordering::Equal
}

/// C++: `str_startswith_nocase` (str.cpp:382).
pub fn startswith_nocase(s: &[u8], prefix: &[u8]) -> bool {
    comp_nocase_num(s, prefix, prefix.len()).is_eq()
}

/// C++: `str_copy`/`str_truncate` into a buffer of `size` bytes: at most `size - 1`
/// bytes, then `str_utf8_fix_truncation`.
pub fn truncate(s: &[u8], size: usize) -> Vec<u8> {
    let mut b = s[..s.len().min(size.saturating_sub(1))].to_vec();
    crate::protocol::packer::utf8_fix_truncation(&mut b);
    b
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn find_and_compare() {
        assert_eq!(tolower_codepoint('Ж' as i32), 'ж' as i32);
        assert_eq!(tolower_codepoint('a' as i32), 'a' as i32);
        assert_eq!(
            utf8_find_nocase("Hello ЖУК".as_bytes(), "жук".as_bytes()),
            Some(6)
        );
        assert_eq!(utf8_find_nocase(b"abc", b"d"), None);
        assert_eq!(utf8_find_nocase(b"abc", b""), Some(0));
        assert!(comp_nocase(b"ABC", b"abd").is_lt());
        assert!(startswith_nocase(b"PAUSE now", b"pause"));
        assert_eq!(truncate("aж".as_bytes(), 3), b"a");
    }
}
